"""Deliberately naive, literal reference implementation."""
import json


class Ref:
    def __init__(self, cfg):
        self.it = cfg["idle_timeout"]
        self.pl = cfg["packet_limit"]
        self.W = cfg["prefix_width"]
        self.rules = [(r["id"], r["class"], r["priority"], [tuple(x) for x in r["ranges"]])
                      for r in cfg["rules"]]
        self.fb = cfg["fallback"]
        self.flows = {}
        self.time = 0
        self.events = []

    def fbclass(self, pre):
        feats = list(pre) + [0] * (self.W - len(pre))
        nd = self.fb
        while "feature" in nd:
            nd = nd["le"] if feats[nd["feature"]] <= nd["threshold"] else nd["gt"]
        return nd["class"]

    def decide(self, fid, c, reason, rule):
        fl = self.flows[fid]
        fl["dec"] = (c, reason, rule, fl["n"], self.time)
        self.events.append({"type": "decision", "flow": fid, "class": c,
                            "reason": reason, "at": fl["n"], "time": self.time,
                            "rule": rule})

    def expire(self, T):
        self.time = T
        fids = sorted(f for f, fl in self.flows.items()
                      if fl["dec"] is None and T - fl["last"] > self.it)
        for fid in fids:
            if self.flows[fid]["dec"] is not None:
                continue
            self.decide(fid, self.fbclass(self.flows[fid]["pre"]), "idle", None)

    def packet(self, fid, T, s, L):
        self.time = T
        fl = self.flows[fid]
        if fl["fwd"] is None:
            fl["fwd"] = s
            f = L
        else:
            f = L if s == fl["fwd"] else -L
        if len(fl["pre"]) < self.W:
            fl["pre"].append(f)
        fl["feats"].append(f)
        fl["n"] += 1
        fl["last"] = T
        n = fl["n"]
        ms = []
        for (rid, cl, pr, rr) in self.rules:
            k = len(rr)
            if n >= k:
                ok = True
                for i in range(k):
                    lo, hi = rr[i]
                    v = fl["feats"][n - k + i]
                    if not (lo <= v <= hi):
                        ok = False
                        break
                if ok:
                    ms.append((rid, cl, pr, k))
        ms.sort(key=lambda x: x[0])
        fl["matches"] += len(ms)
        for (rid, cl, pr, k) in ms:
            self.events.append({"type": "match", "flow": fid, "rule": rid,
                                "start": n - k, "end": n})
        if fl["dec"] is None and ms:
            best = ms[0]
            for m in ms[1:]:
                if (m[2] > best[2] or
                        (m[2] == best[2] and (m[3] > best[3] or
                                              (m[3] == best[3] and m[0] < best[0])))):
                    best = m
            self.decide(fid, best[1], "key", best[0])
        if fl["dec"] is None and n >= self.pl:
            self.decide(fid, self.fbclass(fl["pre"]), "packet_limit", None)

    def handle(self, req):
        self.events = []
        op = req["op"]
        if op == "open":
            self.expire(req["time"])
            self.flows[req["flow"]] = {"feats": [], "pre": [], "n": 0,
                                       "last": req["time"], "dec": None,
                                       "matches": 0, "fwd": None}
        elif op == "chunk":
            for p in req["packets"]:
                self.expire(p["time"])
                self.packet(p["flow"], p["time"], p["source"], p["length"])
        elif op == "tick":
            self.expire(req["time"])
        elif op == "close":
            self.expire(req["time"])
            fid = req["flow"]
            fl = self.flows[fid]
            if fl["dec"] is None:
                self.decide(fid, self.fbclass(fl["pre"]), "end", None)
            c, reason, rule, at, tm = fl["dec"]
            self.events.append({"type": "closed", "flow": fid, "packets": fl["n"],
                                "matches": fl["matches"], "class": c,
                                "reason": reason, "rule": rule})
            del self.flows[fid]
        elif op == "checkpoint":
            return {"checkpoint": self.snapshot()}
        elif op == "restore":
            self.load(req["checkpoint"])
        else:
            raise AssertionError(op)
        return {"events": self.events}

    def snapshot(self):
        return {"__ref__": True,
                "t": self.time,
                "f": {str(k): {"feats": v["feats"], "pre": v["pre"], "n": v["n"],
                               "last": v["last"],
                               "dec": None if v["dec"] is None else list(v["dec"]),
                               "matches": v["matches"], "fwd": v["fwd"]}
                      for k, v in self.flows.items()}}

    def load(self, snap):
        assert snap.get("__ref__") is True
        self.time = snap["t"]
        self.flows = {}
        for k, v in snap["f"].items():
            self.flows[int(k)] = {"feats": list(v["feats"]), "pre": list(v["pre"]),
                                  "n": v["n"], "last": v["last"],
                                  "dec": None if v["dec"] is None else tuple(v["dec"]),
                                  "matches": v["matches"], "fwd": v["fwd"]}
